SantaResult findFloors(std::string directions)
{
    int finalFloor { 0 };
    int basementPosition { -1 };

    for(int i = 0; i < directions.length(); i++)
    {
        if(directions[i] == '(')
        {
            finalFloor++;
        }
        else if(directions[i] == ')')
        {
            finalFloor--;
        }

        if(finalFloor == -1 && basementPosition == -1)
        {
            basementPosition = i + 1;
        }
    }

    return {finalFloor, basementPosition};
}   
